/* ------------------------------------------------------------------ boards */

export interface BoardRef {
  id: string;
  name: string;
  /** Platform ids from the Code Lab that map to this board. */
  platforms: string[];
  logic: string;
  input: string;
  digital: string;
  analog: string;
  pwm: string;
  special: string[];
  notes: string[];
}

