/* ------------------------------------------------------------------ search */

export interface KnowledgeHit { kind: "Board" | "Component" | "Snippet" | "Topic" | "Formula" | "Safety"; title: string; detail: string; id: string }

export function searchKnowledge(q: string): KnowledgeHit[] {
  const s = q.trim().toLowerCase();
  if (!s) return [];
  const hits: KnowledgeHit[] = [];
  const has = (...parts: Array<string | undefined>) => parts.filter(Boolean).join(" ").toLowerCase().includes(s);

  BOARDS.forEach((b) => has(b.name, b.special.join(" "), b.analog, b.digital) &&
    hits.push({ kind: "Board", id: b.id, title: b.name, detail: `${b.logic} · ${b.analog}` }));
  COMPONENTS.forEach((c) => has(c.name, c.purpose, c.library, c.interface) &&
    hits.push({ kind: "Component", id: c.id, title: c.name, detail: c.purpose }));
  SNIPPETS.forEach((c) => has(c.title, c.what, c.platform) &&
    hits.push({ kind: "Snippet", id: c.id, title: c.title, detail: c.what }));
  SYLLABUS.forEach((u) => u.topics.forEach((t) => has(t.topic, t.core, t.projectHook, u.subject) &&
    hits.push({ kind: "Topic", id: `${u.subject}-${t.topic}`, title: `${t.topic} — ${u.subject} (${u.classes})`, detail: t.core })));
  FORMULAS.forEach((f) => has(f.name, f.expr, f.where, f.subject) &&
    hits.push({ kind: "Formula", id: f.name, title: `${f.name}: ${f.expr}`, detail: f.where }));
  SAFETY_RULES.forEach((g) => g.rules.forEach((r, i) => has(r, g.title) &&
    hits.push({ kind: "Safety", id: `${g.title}-${i}`, title: g.title, detail: r })));

  return hits.slice(0, 40);
}

/** Components most relevant to a Code Lab platform — used for the inline reference. */
export function componentsForPlatform(platformId: string): ComponentRef[] {
  if (platformId === "opencv" || platformId === "ml-python" || platformId === "python" || platformId === "web") {
    return COMPONENTS.filter((c) => ["sd", "esp-wifi"].includes(c.id));
  }
  return COMPONENTS.filter((c) => c.category !== "Power");
}

export function snippetsForPlatform(platformId: string): SnippetRef[] {
  const family: Record<string, string[]> = {
    "arduino-uno": ["arduino-uno"],
    "arduino-mega": ["arduino-uno"],
    esp32: ["esp32", "arduino-uno"],
    esp8266: ["esp32", "arduino-uno"],
    "raspberry-pi": ["raspberry-pi", "python"],
    micropython: ["micropython"],
    python: ["python"],
    "ml-python": ["ml-python", "python"],
    opencv: ["opencv", "python"],
    web: ["web"],
  };
  const keys = family[platformId] ?? [];
  return SNIPPETS.filter((s) => keys.includes(s.platform));
}
